//! Bounded C40 keyboard boundary metadata. Never accepts text or native objects.
use std::sync::atomic::{AtomicU64,Ordering};
pub const LIMIT:u64=2048;
static NEXT:AtomicU64=AtomicU64::new(0);
#[derive(Clone,Copy,Debug)]
pub enum Stage{NativeProposed,NativeProposedReturned,NativeChanged,NativeUnicodeKeysBegin,NativeUnicodeKeysReturned,NativeUtf8Ready,NativeTextSent,NativeChangedReturned,SdlTextQueued,ResponderDispatch,ResponderAccepted,InsertBegin,ReplacementAllocated,CurrentTextRead,DelegateBegin,DelegateReturned,AppendBegin,AppendReturned,SetTextBegin,NotificationBegin,NotificationReturned,SetTextReturned,DisplayInvalidated,InsertComplete,BackspaceBegin,ReturnBegin}
impl Stage{fn name(self)->&'static str{match self{Self::NativeProposed=>"native_proposed",Self::NativeProposedReturned=>"native_proposed_returned",Self::NativeChanged=>"native_changed",Self::NativeUnicodeKeysBegin=>"native_unicode_keys_begin",Self::NativeUnicodeKeysReturned=>"native_unicode_keys_returned",Self::NativeUtf8Ready=>"native_utf8_ready",Self::NativeTextSent=>"native_text_sent",Self::NativeChangedReturned=>"native_changed_returned",Self::SdlTextQueued=>"sdl_text_queued",Self::ResponderDispatch=>"responder_dispatch",Self::ResponderAccepted=>"responder_accepted",Self::InsertBegin=>"insert_begin",Self::ReplacementAllocated=>"replacement_allocated",Self::CurrentTextRead=>"current_text_read",Self::DelegateBegin=>"delegate_begin",Self::DelegateReturned=>"delegate_returned",Self::AppendBegin=>"append_begin",Self::AppendReturned=>"append_returned",Self::SetTextBegin=>"set_text_begin",Self::NotificationBegin=>"notification_begin",Self::NotificationReturned=>"notification_returned",Self::SetTextReturned=>"set_text_returned",Self::DisplayInvalidated=>"display_invalidated",Self::InsertComplete=>"insert_complete",Self::BackspaceBegin=>"backspace_begin",Self::ReturnBegin=>"return_begin"}}}
#[derive(Clone,Copy,Default,Debug)]
pub struct Meta{pub field:u32,pub delegate:u32,pub current_units:u32,pub replacement_units:u32,pub location:u32,pub aux:u32,pub thread:u32,pub pc:u32,pub lr:u32,pub sp:u32}
fn reserve(counter:&AtomicU64)->Option<u64>{counter.fetch_update(Ordering::Relaxed,Ordering::Relaxed,|n|(n<=LIMIT).then_some(n.saturating_add(1))).ok()}
fn format_event(sequence:u64,stage:Stage,m:Meta)->String{format!("{{\"event\":\"keyboard_trace\",\"sequence\":{sequence},\"stage\":\"{}\",\"field\":{},\"delegate\":{},\"current_utf16_units\":{},\"replacement_utf16_units\":{},\"location\":{},\"aux\":{},\"guest_thread\":{},\"pc\":{},\"lr\":{},\"sp\":{},\"text_contents_logged\":false}}",stage.name(),m.field,m.delegate,m.current_units,m.replacement_units,m.location,m.aux,m.thread,m.pc,m.lr,m.sp)}
pub fn record(stage:Stage,m:Meta){let Some(n)=reserve(&NEXT)else{return;};if n==LIMIT{crate::diagnostics::event("{\"event\":\"keyboard_trace_limit\",\"limit\":2048,\"text_contents_logged\":false}");}else{crate::diagnostics::event(&format_event(n,stage,m));}}
pub fn native(code:i32,current_units:u32,replacement_units:u32){let stage=match code{1=>Stage::NativeProposed,2=>Stage::NativeProposedReturned,3=>Stage::NativeChanged,4=>Stage::NativeUnicodeKeysBegin,5=>Stage::NativeUnicodeKeysReturned,6=>Stage::NativeUtf8Ready,7=>Stage::NativeTextSent,8=>Stage::NativeChangedReturned,_=>return};record(stage,Meta{current_units,replacement_units,..Default::default()});}
#[cfg(test)]mod tests{use super::*;
 #[test]fn bounded_counter_emits_one_limit_and_stops(){let n=AtomicU64::new(0);for i in 0..=LIMIT{assert_eq!(reserve(&n),Some(i));}for _ in 0..100{assert_eq!(reserve(&n),None);}assert_eq!(n.load(Ordering::Relaxed),LIMIT+1);}
 #[test]fn concurrent_reservations_stay_bounded_and_unique(){let n=std::sync::Arc::new(AtomicU64::new(0));let handles:Vec<_>=(0..8).map(|_|{let n=n.clone();std::thread::spawn(move||(0..1024).filter_map(|_|reserve(&n)).collect::<Vec<_>>())}).collect();let mut v:Vec<_>=handles.into_iter().flat_map(|h|h.join().unwrap()).collect();v.sort_unstable();assert_eq!(v,(0..=LIMIT).collect::<Vec<_>>());}
 #[test]fn metadata_schema_is_numeric_and_does_not_accept_text(){let m=Meta{field:u32::MAX,delegate:1,current_units:7,replacement_units:2,location:7,aux:1,thread:3,pc:0x1234,lr:0x5678,sp:0x9000};let s=format_event(18,Stage::DelegateReturned,m);assert!(s.contains("\"stage\":\"delegate_returned\""));assert!(s.contains("\"replacement_utf16_units\":2"));assert!(s.contains("\"text_contents_logged\":false"));assert!(!s.contains("replacementString"));assert!(s.ends_with('}'));}
 #[test]fn all_native_stages_are_fixed_identifiers(){for s in [Stage::NativeProposed,Stage::NativeProposedReturned,Stage::NativeChanged,Stage::NativeUnicodeKeysBegin,Stage::NativeUnicodeKeysReturned,Stage::NativeUtf8Ready,Stage::NativeTextSent,Stage::NativeChangedReturned]{assert!(s.name().bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||b==b'_'));}}
}
